CREATE TABLE [purchase].[PurchaseExpenses]([PurchaseExpenseId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseExpenses_Id] DEFAULT NEWSEQUENTIALID(),[PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL,[ExpenseType] NVARCHAR(50) NOT NULL,[Description] NVARCHAR(250) NULL,[Amount] DECIMAL(18,2) NOT NULL,[IsTaxable] BIT NOT NULL CONSTRAINT [DF_PurchaseExpenses_Taxable] DEFAULT 0,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchaseExpenses_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_PurchaseExpenses] PRIMARY KEY([PurchaseExpenseId]),CONSTRAINT [FK_PurchaseExpenses_Invoice] FOREIGN KEY([PurchaseInvoiceId]) REFERENCES [purchase].[PurchaseInvoices]([PurchaseInvoiceId]) ON DELETE CASCADE,CONSTRAINT [CK_PurchaseExpenses_Amount] CHECK([Amount]>=0));
